#include <iostream>

class Num {
    int v_;
public:
    Num(int v = 0) : v_(v) {}
    Num& operator=(const Num& o) {
        if (this == &o) {              // 自赋值保护：不保护会在释放旧资源后悬空
            std::cout << "self ";
            return *this;
        }
        v_ = o.v_;
        return *this;                  // 返回引用以支持链式赋值
    }
    int get() const { return v_; }
};

int main() {
    Num a(5);
    a = a;                 // 自赋值
    Num b(9);
    a = b;
    std::cout << a.get();
}
